"""Publish aggregate results only; raw COCO photographs/fixations remain local."""
from pathlib import Path
import argparse,json,shutil,html,os,csv
os.environ.setdefault('MPLCONFIGDIR',str(Path.cwd()/'.cache/matplotlib'))
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import pandas as pd

def main():
 p=argparse.ArgumentParser();p.add_argument('evaluation');p.add_argument('--perception',nargs='+',required=True);p.add_argument('--out',default='reports/phase2');a=p.parse_args();source=Path(a.evaluation);out=Path(a.out);out.mkdir(parents=True,exist_ok=True)
 report=json.loads((source/'report.json').read_text(encoding='utf-8'));table=pd.read_csv(source/'summary.csv').set_index('variant');profiles=[json.loads(Path(x).read_text(encoding='utf-8')) for x in a.perception]
 for name in ['summary.csv','by-image.csv','by-participant.csv','trials.csv']:shutil.copy2(source/name,out/name)
 (out/'empirical-report.json').write_text(json.dumps(report,indent=2,allow_nan=False),encoding='utf-8')
 for i,profile in enumerate(profiles):
  profile['image']=Path(profile['image']).name;(out/f'perception-{i+1}.json').write_text(json.dumps(profile,indent=2),encoding='utf-8')
 display={'full':'Full V2','center':'Center prior','random_center':'Broad center random','random_walk':'Random walk','salience':'Salience','salience_ior':'Salience + IOR','without_semantics':'Without semantics','without_depth':'Without depth','without_information':'Without information','without_memory':'Without object memory','without_uncertainty':'Fixed policy uncertainty','without_novelty':'Without novelty','without_history':'Without history','without_exploration':'Without exploration'}
 order=['full','center','random_walk','random_center','salience','salience_ior','without_semantics','without_depth','without_information','without_memory','without_uncertainty','without_novelty','without_history','without_exploration'];table=table.loc[order]
 fig,axs=plt.subplots(1,2,figsize=(12,7),sharey=True);y=list(range(len(order)));colors=['#187765' if n=='full' else '#b36d37' if n=='center' else '#8195a2' for n in order]
 axs[0].barh(y,table.nss,color=colors);axs[0].set_yticks(y,[display[n] for n in order]);axs[0].invert_yaxis();axs[0].set_xlabel('NSS (higher is better)');axs[0].axvline(0,color='black',lw=.6);axs[1].barh(y,table.spatial_dtw,color=colors);axs[1].set_xlabel('Custom spatial DTW (lower is better)')
 fig.suptitle('COCO-Search18 exploratory internal test: full model does not beat center bias');fig.text(.02,.012,'6 internal test images · 10 participants · 60 trials · 3 seeds/variant · no fitting or significance claims\nImage-balanced descriptive means; official source was the public training split. Measured human RT conditions the model budget.',fontsize=9);fig.tight_layout(rect=(0,.065,1,.96));fig.savefig(out/'empirical-comparison.png',dpi=160);plt.close(fig)
 full=table.loc['full'];center=table.loc['center'];nod=table.loc['without_depth'];duration=float(full['human_mean_duration_ms']);headers=['Model / component removal','NSS ↑','AUC ↑','Custom DTW ↓','Mean duration (ms)','Mean post-initial count','Mean movement (px)','Refixation rate']
 rows=''.join('<tr>'+''.join('<td>'+html.escape(v)+'</td>' for v in [display[name],f'{r.nss:.3f}',f'{r.auc_fixation_vs_nonfixation_pixels:.3f}',f'{r.spatial_dtw:.3f}',f'{r.model_mean_duration_ms:.1f}',f'{r.model_fixation_count:.2f}',f'{r.model_mean_amplitude_px:.1f}',f'{r.model_refixation_rate:.3f}'])+'</tr>' for name,r in table.iterrows())
 speed_rows=''
 for profile in profiles:
  timings=profile['fixations'];speed_rows+='<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in [profile['image'],f"{profile['load_seconds']:.2f} s",f"{profile['depth_first_seconds']:.3f} s",f"{profile['depth_cached_seconds']:.3f} s",f"{sum(x['cold_seconds'] for x in timings)/len(timings):.3f} s",f"{sum(x['cached_seconds'] for x in timings)/len(timings):.4f} s",f"{profile['memory']['peak_process_rss_mb']:.1f} MiB",sum(len(x['semantic']) for x in timings)])+'</tr>'
 page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RGB Observer V2 · implementation and validation</title><style>body{{font:16px/1.7 system-ui;color:#21333b;background:#f7faf9;max-width:1200px;margin:36px auto;padding:0 20px}}h1{{font-size:30px;line-height:1.25}}h2{{font-size:23px;margin-top:30px}}.notice{{padding:20px;background:#fff1d7;border-left:4px solid #b87422}}a{{color:#167763}}img{{width:100%;height:auto}}.scroll{{overflow:auto}}table{{border-collapse:collapse;width:100%;font-size:13px;white-space:nowrap}}th,td{{padding:10px;border-bottom:1px solid #d3dddc;text-align:left}}th{{background:#e2eeea}}code{{overflow-wrap:anywhere}}li{{margin:7px 0}}</style>
<h1>RGB Active Observer V2: operational perception, actual-state 2.5D memory and an empirical pilot</h1><p class="notice"><b>The engineering is working; human likeness is not established.</b> The full model remains behind the center-prior baseline on density and sequence measures. The sample is small and comes from an internal split of released training images. No parameter fitting or population significance claim is made.</p>
<p><a href="../index.html">Return to the interactive scene explorer</a> · <a href="empirical-report.json">Evaluation metadata and aggregate results</a> · <a href="summary.csv">Summary CSV</a> · <a href="by-image.csv">Image-level CSV</a> · <a href="by-participant.csv">Participant-level CSV</a></p>
<h2>What was actually implemented and tested</h2><p>Pinned, SHA256-verified SSDLite320 MobileNetV3 and MiDaS Small run on CPU. Semantic detections are admitted only centrally from a foveated context crop; full-image semantic detections never become a hidden search bank. The depth map is private sensor output; central observed samples alone update memory. The same provider factory and caches are used by run-one, prepared previews and empirical evaluation.</p><p>Object memory now separates identity, image-position and depth uncertainty, observation count, exposure time, relative depth dispersion and relative 3D envelopes. Association rejects strong class conflicts and retains previously observed partial extents. Duration-dependent evidence is capped by a sensory ceiling. A computational expected-reduction proxy and bounded stay action are added, while legacy evidence and uncertainty×novelty remain selectable baselines. Stay segments are merged for fixation metrics.</p>
<h2>Actual photograph inference measurements</h2><div class="scroll"><table><thead><tr>{''.join('<th>'+h+'</th>' for h in ['Photograph','Load','Depth first call','Depth cache','Detector first calls','Detector cache','Peak process RSS','Central semantic detections'])}</tr></thead><tbody>{speed_rows}</tbody></table></div><p>Times are observed wall-clock measurements on this CPU, with other jobs sometimes running, not controlled production throughput. Memory is whole-process peak RSS including Python and both models. First-call measurements in these two reports were made with previously empty corresponding cache entries. Semantic detection counts demonstrate operation, not detection accuracy. No measured depth ground truth was available.</p>
<h2>Empirical protocol</h2><ul><li><b>Task:</b> target-present categorical search from COCO-Search18, via a pinned research mirror.</li><li><b>Splits:</b> 24 available originals sorted by a fixed filename hash: 12 train, 6 validation, 6 internal test images. This is not the official benchmark test split. No weights were fitted on these images.</li><li><b>Completed test:</b> {report['images']} images, {report['participants']} participants, {report['trials']} eligible trials, 3 stochastic seeds and 14 variants: 2,520 model runs. Seeds are averaged within image/participant before image-balanced summaries.</li><li><b>Geometry:</b> reproduce the mirror's black-padding rule to the 1680×1050 display, then uniformly rescale pixels and coordinates to 640×400. Pixel hashes reject train/test duplication. The exact original stimulus pipeline may differ; confirmation needs official display assets. Foveation remains a declared pixel-based approximation.</li><li><b>Timing:</b> the model's viewing budget is conditioned on each human trial RT; human cumulative dwell is truncated at RT. Saccade gaps are unavailable. This evaluates gaze under a supplied duration; it does not predict search response time.</li><li><b>Leakage:</b> only the declared first fixation sets the initial gaze. No subsequent human coordinates, target boxes or dataset semantic annotations enter prediction.</li></ul>
<img src="empirical-comparison.png" alt="Density and sequence comparisons for the full model, baselines and component removals">
<h2>Results: descriptive, image-balanced means</h2><div class="scroll"><table><thead><tr>{''.join('<th>'+h+'</th>' for h in headers)}</tr></thead><tbody>{rows}</tbody></table></div>
<p>Human reference mean duration: <b>{duration:.1f} ms</b>; full model: <b>{full.model_mean_duration_ms:.1f} ms</b>. Human mean post-initial count: {full.human_fixation_count:.2f}; full model: {full.model_fixation_count:.2f}. Full-model NSS {full.nss:.3f} versus center-prior {center.nss:.3f}; DTW {full.spatial_dtw:.3f} versus {center.spatial_dtw:.3f}.</p>
<p>Removing depth changes NSS by {nod.nss-full.nss:+.3f} and DTW by {nod.spatial_dtw-full.spatial_dtw:+.3f}. This is a descriptive association within this configuration, not evidence of physical depth accuracy or a statistically established contribution. Semantic and other removal effects must likewise be read across several metrics. A mechanism that improves density can worsen timing or sequence fit.</p>
<h2>Metric definitions and scope</h2><p>NSS and heatmap correlation use generated duration-weighted densities. AUC uses deterministic nonfixated-pixel negatives and tie-correct SciPy ranks; it is not branded AUC-Judd. Sequence distance is our documented custom spatial DTW, not MultiMatch. Durations/amplitudes and refixations are available per trial/image/participant. The completed pilot reports per-trial mean timing/movement summaries; event-distribution Wasserstein functions are now implemented/tested in the evaluator but are not part of this completed pilot table. Adjacent stay segments are coalesced before scoring.</p>
<h2>Limitations and next scientific priorities</h2><ul><li>Only six internal test images and ten participants. No reliable population inference or significance ranking is claimed.</li><li>The pretrained detector was trained on COCO and may have seen stimulus imagery. Internal image holdout is not a guarantee of vision-model pretraining independence.</li><li>Quality, covariance, expected information and durations are uncalibrated heuristics. Expected reduction can be optimistic for irreducible identity ambiguity.</li><li>Semantic category cues are central; task guidance lacks a learned goal-conditioned peripheral template. Context priors are empty unless explicitly configured.</li><li>Data association can still duplicate after severe crop changes or merge similar nearby regions. Envelopes are partial visible-surface uncertainty, never complete physical object shapes.</li><li>Actual inference is demonstrated on Linux CPU. Windows UTF-8 behavior is regression-tested, but native Windows pretrained inference is not claimed.</li><li>Next: calibrate on training images, audit display/retinal geometry, test parameter sensitivity, then evaluate on additional untouched images. Do not tune against this pilot and call the same images confirmatory.</li></ul>
<p>Source: <a href="https://sites.google.com/view/cocosearch/home">COCO-Search18</a> · <a href="https://github.com/RosenholtzLab/CCP_CSHL/tree/401baae571e325eacb000f21783463d2343609ab">Pinned research mirror</a> · <a href="https://github.com/tamayowang-lab/single-view-image-rectification/tree/feature/rgb-active-observer-v1/rgb-active-observer">Model source and implementation audit</a>. Raw human fixations and COCO photos are not redistributed with this report.</p></html>'''
 (out/'phase2-report.html').write_text(page,encoding='utf-8');print(json.dumps(dict(report=str(out/'phase2-report.html'),full_nss=float(full.nss),center_nss=float(center.nss),full_duration=float(full.model_mean_duration_ms),human_duration=duration)))
if __name__=='__main__':main()
